// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(c));
        amount = bound(amount, 1, type(uint256).max);

        uint256 balanceBefore = receiver.balance;

        // Owner is the test contract by default, so we can call directly
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));

        if (success) {
            uint256 balanceAfter = receiver.balance;
            assertTrue(balanceAfter == balanceBefore + amount, "Receiver balance should increase by amount");
        }
    }
}

