// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver) internal {
        vm.assume(uint160(receiver) > 255 && receiver != address(this) && receiver != address(c));
        vm.deal(address(c), 1 ether);
        address attacker = address(0xBEEF);
        bool reverted;
        vm.prank(attacker, address(this));
        try c.sendTo(receiver, 1) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(address receiver) public {
        _run(receiver);
    }

    receive() external payable {}
}
